style.css:
/* General body styling */
body {
    background-color: #f7d7d7; /* Soft baby pink background */
    font-family: 'Arial', sans-serif; /* Clean, simple font */
    color: #333; /* Dark text color for readability */
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Header (pink with bold, black text) */
h1, h2, h3, h4 {
    font-family: 'Impact', sans-serif; /* Bold, playful font */
    color: #000000; /* Black text for contrast */
    text-align: center;
    margin-top: 20px;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3); /* Adds a subtle shadow */
}

/* Styling links (make them stand out in black or pink) */
a {
    color: #ff66b2; /* Baby pink color for links */
    text-decoration: none;
    font-weight: bold;
}

a:hover {
    color: #ff3385; /* Darker pink for hover effect */
    text-decoration: underline;
}

/* Add a Roblox-inspired button style with pink and black */
button {
    background-color: #ff66b2; /* Baby pink background for buttons */
    color: #000; /* Black text */
    padding: 15px 30px;
    font-size: 16px;
    font-weight: bold;
    border: none;
    border-radius: 5px; /* Rounded edges */
    cursor: pointer;
    transition: background-color 0.3s ease;
}

button:hover {
    background-color: #ff3385; /* Darker pink on hover */
}

/* Add sections with alternating background colors */
section {
    padding: 40px 20px;
    margin: 20px 0;
    background-color: #fff; /* White background for each section */
    border-radius: 10px; /* Rounded corners */
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1); /* Subtle shadow for depth */
}

section:nth-child(even) {
    background-color: #f7d7d7; /* Light baby pink for even sections */
}

/* Style paragraphs with a nice, readable layout */
p {
    font-size: 16px;
    line-height: 1.6;
    color: #333; /* Dark text color */
    text-align: justify;
}

/* Create a footer with a black background */
footer {
    background-color: #000; /* Black background for footer */
    color: white;
    text-align: center;
    padding: 20px;
    font-size: 14px;
    position: fixed;
    width: 100%;
    bottom: 0;
}

/* Style the navbar with black and pink buttons */
nav {
    background-color: #000;
    padding: 10px;
    text-align: center;
}

nav a {
    color: #ff66b2; /* Baby pink for links */
    padding: 10px 20px;
    margin: 0 10px;
    font-size: 16px;
    font-weight: bold;
    text-decoration: none;
    border-radius: 5px;
}

nav a:hover {
    background-color: #ff3385; /* Darker pink for hover effect */
    color: #fff; /* White text on hover */
}
